int create_or_update_file(const char *path, bool parents, usec_t stamp, uid_t uid, gid_t gid, mode_t mode) {
    int fd = -1;
    mode_t default_mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH; // 0644
    mode_t final_mode = mode ? mode : default_mode;

    if (path == NULL)
        return -EINVAL;

    if (parents) {
        // Create parent directories
        char *dir_path = strdup(path);
        if (!dir_path)
            return -ENOMEM;

        char *slash = strrchr(dir_path, '/');
        if (slash) {
            *slash = '\0';
            int r = mkdir_p(dir_path, S_IRWXU | S_IRWXG | S_IRWXO);
            if (r < 0) {
                free(dir_path);
                return r;
            }
        }
        free(dir_path);
    }

    fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, final_mode);
    if (fd < 0)
        return -errno;

    if (uid != (uid_t)-1 && gid != (gid_t)-1) {
        if (fchown(fd, uid, gid) < 0) {
            close(fd);
            return -errno;
        }
    }

    if (stamp > 0) {
        struct timespec ts[2];
        ts[0].tv_sec = stamp / 1000000;
        ts[0].tv_nsec = (stamp % 1000000) * 1000;
        ts[1] = ts[0]; // Same for atime

        if (futimens(fd, ts) < 0) {
            close(fd);
            return -errno;
        }
    }

    close(fd);
    return 0;
}

