// Helper function to create parent directories
static int create_parents(const char *path) {
    char *buf = strdup(path);
    if (!buf)
        return -ENOMEM;

    char *p = buf;
    while (*p) {
        if (*p == '/') {
            *p = '\0';
            if (mkdir(buf, 0755) < 0) {
                if (errno != EEXIST) {
                    free(buf);
                    return -errno;
                }
            }
            *p = '/';
        }
        p++;
    }

    if (mkdir(buf, 0755) < 0) {
        if (errno != EEXIST) {
            free(buf);
            return -errno;
        }
    }

    free(buf);
    return 0;
}

int file_set_attributes(const char *path, bool parents, usec_t stamp, uid_t uid, gid_t gid, mode_t mode) {
    int ret = 0;

    // Check if we need to create parent directories
    if (parents) {
        ret = create_parents(path);
        if (ret < 0)
            return ret;
    }

    // Open the file for writing (create if needed)
