int create_or_update_file(const char *path, bool parents, usec_t stamp, uid_t uid, gid_t gid, mode_t mode) {
    int fd = -1;
    mode_t default_mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH; // 0644

    if (!path || *path == '\0') {
        return -EINVAL;
    }

    if (parents) {
        // Create parent directories as needed
        char *slash = strrchr((char *) path, '/');
        if (slash && slash != path) {
            char parent[strlen(path) + 1];
            strncpy(parent, path, slash - path);
            parent[slash - path] = '\0';

            if (mkdir_with_parents(parent, 0755) < 0) {
                return -errno;
            }
        }
    }

    // Open the file for writing
    fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, mode ? mode : default_mode);
    if (fd < 0) {
        return -errno;
    }

    // Set ownership if provided
    if (uid != (uid_t)-1 || gid != (gid_t)-1) {
        if (fchown(fd, uid != (uid_t)-1 ? uid : (uid_t)-1, gid != (gid_t)-1 ? gid : (gid_t)-1) < 0) {
            int err = -errno;
            close(fd);
            return err;
        }
    }

    // Set timestamp
    struct timespec times[2];
    times[0].tv_nsec = UTIME_NOW; // Leave atime as is
    times[1].tv_nsec = stamp;     // Set mtime
    if (futimens(fd, times) < 0) {
        int err = -errno;
        close(fd);
        return err;
    }

    close(fd);
    return 0;
}

