    struct stat st = {0};
    mode_t default_mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH; // 0644

    // If mode is invalid, use default mode
    if (mode == 0) {
        mode = default_mode;
    }

    // Check if path is valid and optionally create parent directories
    if (parents) {
        char *dir_path = strdup(path);
        char *slash = NULL;
        if (!dir_path)
            return -ENOMEM;

        for (slash = dir_path; *slash; slash++) {
            if (*slash == '/') {
                *slash = '\0';
                if (mkdir(dir_path, S_IRWXU | S_IRWXG | S_IRWXO) == -1) {
                    if (errno != EEXIST) {
                        free(dir_path);
                        return -errno;
                    }
                }
                *slash = '/';
            }
        }
        free(dir_path);
    }

    // Open the file
    int fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, mode);
    if (fd == -1) {
        return -errno;
    }

    // Set ownership if provided
    if (uid != (uid_t)-1 || gid != (gid_t)-1) {
        if (fchown(fd, uid, gid) == -1) {
            close(fd);
            return -errno;
        }
    }

    // Set file timestamps
    struct timespec times[2];
    times[0].tv_sec = stamp / 1000000;
    times[0].tv_nsec = (stamp % 1000000) * 1000;
    times[1] = times[0]; // Set both atime and mtime to the same value
